package io.knowledgebrain.learning;
import java.util.*;import java.time.*;import java.nio.charset.StandardCharsets;import org.junit.jupiter.api.*;import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;import static org.junit.jupiter.api.Assertions.*;import org.apache.kafka.clients.consumer.*;import io.knowledgebrain.contracts.learning.githubevidence.v1.*;
@EnabledIfEnvironmentVariable(named="BRAIN_TEST_LEARNING_KAFKA_BOOTSTRAP",matches=".+")
class GitHubEvidenceKafkaIntegrationTest extends GitHubEvidenceFixtures {
 @Test void bothExactImmutableStreamsArriveThroughRealConnectWithPrivatePinsAndTrace()throws Exception{githubInit();var e=github();var session=session(node);var linked=link(e.evidenceId(),"GITHUB",session,0);github.change(space,roadmap,e.evidenceId(),actor,1,"Corrected",false,trace);links.change(space,roadmap,e.evidenceId(),"GITHUB",actor,1,new EvidenceSessionStore.Input(null,null),trace);github.change(space,roadmap,e.evidenceId(),actor,2,null,true,trace);var expected=new HashMap<String,byte[]>();sql.query("SELECT id,payload FROM outbox_event WHERE aggregateid IN (?,?)",(rs,n)->Map.entry(rs.getObject(1,UUID.class).toString(),rs.getBytes(2)),e.evidenceId(),linked.linkId()).forEach(x->expected.put(x.getKey(),x.getValue()));assertEquals(5,expected.size());var options=new LearningStudyKafkaIntegrationTest().options();options.put("group.id","learning-validation-"+ids.next());options.put("enable.auto.commit","false");options.put("auto.offset.reset","earliest");options.put("key.deserializer",org.apache.kafka.common.serialization.StringDeserializer.class.getName());options.put("value.deserializer",org.apache.kafka.common.serialization.ByteArrayDeserializer.class.getName());options.put("key.deserializer",org.apache.kafka.common.serialization.StringDeserializer.class.getName());options.put("value.deserializer",org.apache.kafka.common.serialization.ByteArrayDeserializer.class.getName());var topics=List.of("learning.github-evidence.v1","learning.github-evidence-session.v1");try(var consumer=new KafkaConsumer<String,byte[]>(options)){consumer.subscribe(topics);var found=new HashSet<String>();var versions=new HashMap<String,List<Long>>();long deadline=System.nanoTime()+Duration.ofSeconds(60).toNanos();while(found.size()<5&&System.nanoTime()<deadline)for(var record:consumer.poll(Duration.ofSeconds(1))){if(!Set.of(e.evidenceId().toString(),linked.linkId().toString()).contains(record.key()))continue;var event=GitHubLearningEventEnvelopeV1.parseFrom(record.value());assertArrayEquals(expected.get(event.getEventId()),record.value());assertEquals(actor.toString(),event.getActorId());assertEquals(space.toString(),event.getSpaceId());assertEquals(trace,event.getTraceId());assertEquals("learning-service",event.getProducer());String artifact;long version;if(record.topic().equals(topics.getFirst())){var p=GitHubEvidenceChangedPayloadV1.parseFrom(event.getPayload());assertEquals(repo.toString(),p.getRepositoryId());assertEquals(commit.toString(),p.getCommitId());assertEquals("PRIVATE",p.getVisibility());assertEquals(1,p.getCommitVersion());assertEquals("a".repeat(40),p.getSha());version=p.getVersion();artifact="github-evidence-events";}else{var p=GitHubEvidenceSessionChangedPayloadV1.parseFrom(event.getPayload());assertEquals("GITHUB",p.getEvidenceKind());assertEquals(e.evidenceId().toString(),p.getEvidenceId());assertEquals("PRIVATE",p.getVisibility());version=p.getVersion();artifact="github-evidence-session-events";}for(var header:Map.of("trace_id",trace,"schema_group","learning","schema_artifact",artifact,"schema_version","1").entrySet()){assertNotNull(record.headers().lastHeader(header.getKey()));assertEquals(header.getValue(),new String(record.headers().lastHeader(header.getKey()).value(),StandardCharsets.UTF_8));}if(found.add(event.getEventId()))versions.computeIfAbsent(record.topic(),x->new ArrayList<>()).add(version);}assertEquals(expected.keySet(),found);assertEquals(List.of(1L,2L,3L),versions.get(topics.getFirst()));assertEquals(List.of(1L,2L),versions.get(topics.getLast()));}}
}
